class BinaryNode(BaseModel):
    """
    Two operands, applied pointwise. `mod` is math.fmod (sign follows the
    dividend), `pow` returns NaN where the result would be complex.
    """

    fn: Fn = Field(..., title='Fn')
    left: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Left')
    op: Literal['binary'] = Field(..., title='Op')
    right: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Right')


class ClampNode(BaseModel):
    """
    Bound a curve to [lo, hi]. Expressible as min(max(x, lo), hi), but that
    reads as arithmetic; this reads as intent, and is one node instead of four
    against the node cap.
    """

    hi: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Hi')
    lo: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Lo')
    op: Literal['clamp'] = Field(..., title='Op')
    operand: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Operand')


class CmpNode(BaseModel):
    """
    A comparison as a 0/1 mask, so it composes with ordinary arithmetic:
    multiply by it to gate a term, or feed it to `cond` as a branch test.
    NaN on either side yields NaN, never a silent False.
    """

    fn: Fn1 = Field(..., title='Fn')
    left: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Left')
    op: Literal['cmp'] = Field(..., title='Op')
    right: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Right')


class CoalesceNode(BaseModel):
    """
    Replace a non-finite result with a fallback. The ONLY node that does not
    propagate NaN — everything else does, so without this a single divide-by-zero
    silently removes that step from the curve rather than showing a chosen value.
    """

    fallback: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Fallback')
    op: Literal['coalesce'] = Field(..., title='Op')
    operand: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Operand')


class CondNode(BaseModel):
    """
    Piecewise selection: `when` non-zero picks `then`, zero picks
    `otherwise`. The guard for divide-by-zero — `cond(b != 0, a / b, 0)` keeps
    the step instead of dropping it as non-finite.
    """

    op: Literal['cond'] = Field(..., title='Op')
    otherwise: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Otherwise')
    then: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Then')
    when: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='When')


class MetricViewCreate(BaseModel):
    name: str = Field(..., max_length=200, min_length=1, title='Name')
    spec: MetricViewSpec


class MetricViewPatch(BaseModel):
    name: Name2 | None = Field(None, title='Name')
    spec: MetricViewSpec | None = None


class MetricViewPreviewRequest(BaseModel):
    """
    Un-persisted evaluation — powers the create/edit dialog's live preview.
    """

    max_points: MaxPoints | None = Field(
        2000, title='Max Points', validate_default=True
    )
    spec: MetricViewSpec
    step_from: int | None = Field(None, title='Step From')
    step_to: int | None = Field(None, title='Step To')
    wall_clock_from: float | None = Field(None, title='Wall Clock From')
    wall_clock_to: float | None = Field(None, title='Wall Clock To')


class MetricViewSpec(BaseModel):
    expression: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Expression')


class ReduceNode(BaseModel):
    """
    Collapse the whole curve to one number, broadcast back over every step.

    This is what makes normalization expressible: a z-score is
    `(x - reduce(mean, x)) / reduce(std, x)`, and min-max is
    `(x - reduce(min, x)) / (reduce(max, x) - reduce(min, x))`.

    Non-finite values are excluded from the statistic — a summary that one
    divide-by-zero turns into NaN would take the entire output curve with it.
    A curve with nothing finite in it reduces to NaN.

    SCOPE: the statistic is taken over the ALIGNED grid, which is the inner join
    across every leaf in the expression — not over the operand's whole stored
    curve. `zscore(a)` alone standardizes over all of `a`; the same expression
    with a sparse `b` in it standardizes over the steps `a` and `b` share. That
    follows from evaluating one expression on one grid, and it is the honest
    reading (the output only exists where the join does), but it is worth
    knowing before comparing a normalized curve against a differently-scoped
    one. The same applies to `scan` and `window`.
    """

    fn: Fn2 = Field(..., title='Fn')
    op: Literal['reduce'] = Field(..., title='Op')
    operand: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Operand')


class ScanNode(BaseModel):
    """
    A running value over the step axis — the first operators that are NOT
    pointwise. `cummax` is "best so far", the most-asked-for derived curve;
    `delta` is step-over-step change.

    Non-finite inputs are excluded and the scan continues, matching `_sma` in
    the telemetry store: one divide-by-zero mid-curve must not destroy every
    step after it. `delta` is the exception — it is a difference, not an
    accumulation, so a missing endpoint yields NaN for that step alone.
    """

    fn: Fn3 = Field(..., title='Fn')
    op: Literal['scan'] = Field(..., title='Op')
    operand: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Operand')


class ShiftNode(BaseModel):
    """
    Move a curve along the step axis. Positive `by` looks BACK (x[i-by]),
    negative looks forward. Steps with no counterpart are NaN — shifting must
    not wrap or clamp, which would compare a value against itself.
    """

    by: int = Field(..., ge=-5000, le=5000, title='By')
    op: Literal['shift'] = Field(..., title='Op')
    operand: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Operand')


class SmoothNode(BaseModel):
    """
    Smoothing INSIDE the expression (EMA(loss_a / loss_b) differs from
    EMA-ing the rendered output). Reuses the store's _ema/_sma at the aligned
    grid's full resolution. ema uses `factor`, sma uses `window`.
    """

    factor: float | None = Field(0.6, ge=0.0, lt=1.0, title='Factor')
    fn: Fn4 = Field(..., title='Fn')
    op: Literal['smooth'] = Field(..., title='Op')
    operand: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Operand')
    window: int | None = Field(10, ge=1, le=5000, title='Window')


class UnaryNode(BaseModel):
    """
    One operand, applied pointwise. Anything mathematically undefined at a
    step (log of a negative, asin out of domain) becomes NaN there and is
    dropped-and-counted at the end, never an error that kills the whole read.
    """

    fn: Fn5 = Field(..., title='Fn')
    op: Literal['unary'] = Field(..., title='Op')
    operand: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Operand')


class WindowNode(BaseModel):
    """
    A trailing-window reduction. `mean` duplicates SmoothNode's sma on
    purpose: this node is where the rest of the window statistics live, and
    splitting mean off from std would be a trap.

    Partial windows at the start use what is available, and non-finite values
    are excluded from every window they touch (the store's `_sma` convention).
    """

    fn: Fn6 = Field(..., title='Fn')
    op: Literal['window'] = Field(..., title='Op')
    operand: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Operand')
    window: int | None = Field(10, ge=1, le=5000, title='Window')


